#!/usr/bin/env node
/* The published `scriptc-c-embed` command. Thin on purpose: every argument,
 * profile decision, and generated byte lives in the compiled library, so the
 * tests exercise exactly what users run. */
import { runEmbedCli } from "../dist/cli.js";

const outcome = await runEmbedCli(process.argv.slice(2), { cwd: process.cwd() });
if (outcome.stdout.length > 0) process.stdout.write(outcome.stdout);
if (outcome.stderr.length > 0) process.stderr.write(outcome.stderr);
process.exitCode = outcome.exitCode;
